import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_kernel_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cmath>

__device__ float gelu(float x) {
    return 0.5f * x * (1.0f + erff(x / sqrtf(2.0f)));
}

__global__ void fused_kernel(const float* input, const float* bias, float* output, 
                             int N, int C, int H, int W) {
    int n = blockIdx.x;
    int w = blockIdx.y;
    int c = threadIdx.x;

    if (n >= N || w >= W || c >= C) return;

    float sum = 0.0f;

    // Shared memory for block-wide reductions
    __shared__ float smin[16];

    for (int h = 0; h < H; ++h) {
        // Load input value for current h
        int input_idx = ((n * C + c) * H + h) * W + w;
        float val = input[input_idx];

        smin[c] = val;
        __syncthreads();

        // Block-wide min reduction
        for (int offset = blockDim.x/2; offset>0; offset>>=1) {
            if (c < offset) {
                smin[c] = fminf(smin[c], smin[c+offset]);
            }
            __syncthreads();
        }

        sum += smin[0];
        __syncthreads();
    }

    // Apply GELU and add bias
    float out_val = gelu(sum) + bias[c];
    int output_idx = (n * C + c) * W + w;
    output[output_idx] = out_val;
}

torch::Tensor fused_operation_cuda(torch::Tensor input, torch::Tensor bias) {
    TORCH_CHECK(input.is_cuda(), "Input must be CUDA tensor");
    TORCH_CHECK(input.dim() == 4, "Input must be 4D tensor");

    int N = input.size(0);
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);

    auto output = torch::zeros({N, C, 1, W}, input.options());

    dim3 grid(N, W);
    dim3 block(C);

    fused_kernel<<<grid, block>>>(
        input.contiguous().data_ptr<float>(),
        bias.contiguous().data_ptr<float>(),
        output.data_ptr<float>(),
        N, C, H, W
    );

    return output;
}
"""

fused_cpp_source = "torch::Tensor fused_operation_cuda(torch::Tensor input, torch::Tensor bias);"

fused_extension = load_inline(
    name='fused_operation',
    cpp_sources=fused_cpp_source,
    cuda_sources=fused_kernel_source,
    functions=['fused_operation_cuda'],
    verbose=True,
    extra_cflags=['-O3'],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, output_padding, bias_shape):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose2d(
            in_channels, out_channels, kernel_size, 
            stride, padding, output_padding
        )
        self.bias = nn.Parameter(torch.randn(bias_shape))
        self.fused_op = fused_extension.fused_operation_cuda

    def forward(self, x):
        x = self.conv_transpose(x)
        x = self.fused_op(x, self.bias)
        return x
